// DRINKOO – one-slide deck generated by pptxgenjs (PPTX Skill pattern)
const PptxGenJS = require("pptxgenjs");
const path = require("path");

const pptx = new PptxGenJS();

pptx.layout = "LAYOUT_WIDE"; // 13.33 x 7.5 inches

// ── Colour tokens ──────────────────────────────────────────────────────────
const C = {
  bg:       "1A1A2E",  // deep navy
  panel:    "16213E",  // slightly lighter navy panel
  orange:   "FF6B2D",  // DRINKOO brand orange
  teal:     "0E8F8F",  // DRINKOO brand teal
  white:    "FFFFFF",
  offWhite: "F4EFE6",
  muted:    "A0A8B8",
  good:     "02C39A",  // stat positive
  tagline:  "FFD6BC",  // warm tint
};

const slide = pptx.addSlide();

// ── Full background ────────────────────────────────────────────────────────
slide.addShape(pptx.ShapeType.rect, {
  x: 0, y: 0, w: "100%", h: "100%",
  fill: { color: C.bg },
  line: { color: C.bg },
});

// ── Left accent bar ────────────────────────────────────────────────────────
slide.addShape(pptx.ShapeType.rect, {
  x: 0, y: 0, w: 0.07, h: "100%",
  fill: { color: C.orange },
  line: { color: C.orange },
});

// ── Top brand strip ───────────────────────────────────────────────────────
slide.addShape(pptx.ShapeType.rect, {
  x: 0.07, y: 0, w: "100%", h: 0.06,
  fill: { color: C.teal },
  line: { color: C.teal },
});

// ── Hero title block ──────────────────────────────────────────────────────
slide.addText("DRINKOO", {
  x: 0.45, y: 0.28, w: 5.5, h: 1.0,
  fontSize: 68, bold: true,
  color: C.white,
  fontFace: "Arial Black",
  charSpacing: 8,
});

slide.addText("SKU Management & Distribution Platform", {
  x: 0.45, y: 1.22, w: 6.2, h: 0.42,
  fontSize: 16,
  color: C.tagline,
  fontFace: "Trebuchet MS",
  italic: true,
});

// ── Orange divider line ───────────────────────────────────────────────────
slide.addShape(pptx.ShapeType.rect, {
  x: 0.45, y: 1.72, w: 3.8, h: 0.04,
  fill: { color: C.orange },
  line: { color: C.orange },
});

// ── KPI stat cards (4 stats side by side) ─────────────────────────────────
const stats = [
  { val: "50",    label: "Active SKUs",      sub: "7 categories" },
  { val: "37",    label: "States & UTs",     sub: "All India" },
  { val: "978",   label: "Customers",        sub: "Population-weighted" },
  { val: "3,932", label: "Sales Transactions", sub: "Last 30 days" },
];

const cardW = 2.7;
const cardH = 1.55;
const cardY = 2.05;
const gap   = 0.2;
const startX = 0.45;

stats.forEach((s, i) => {
  const cx = startX + i * (cardW + gap);

  // Card background
  slide.addShape(pptx.ShapeType.roundRect, {
    x: cx, y: cardY, w: cardW, h: cardH,
    rectRadius: 0.12,
    fill: { color: C.panel },
    line: { color: C.teal, size: 1 },
  });

  // Big number
  slide.addText(s.val, {
    x: cx + 0.12, y: cardY + 0.12, w: cardW - 0.24, h: 0.72,
    fontSize: 44, bold: true,
    color: C.orange,
    fontFace: "Arial Black",
    align: "center",
  });

  // Label
  slide.addText(s.label, {
    x: cx + 0.1, y: cardY + 0.82, w: cardW - 0.2, h: 0.34,
    fontSize: 13, bold: true,
    color: C.white,
    fontFace: "Trebuchet MS",
    align: "center",
  });

  // Sub-label
  slide.addText(s.sub, {
    x: cx + 0.1, y: cardY + 1.16, w: cardW - 0.2, h: 0.26,
    fontSize: 10,
    color: C.muted,
    fontFace: "Calibri",
    align: "center",
  });
});

// ── Feature bullet rows ───────────────────────────────────────────────────
const features = [
  { icon: "⚡", text: "Real-time sales ingestion & state-wise analytics dashboard" },
  { icon: "🔒", text: "JWT-secured backend with read-only AI text-to-SQL chatbot" },
  { icon: "📦", text: "Shipment orchestration & observability logging out of the box" },
];

features.forEach((f, i) => {
  const fy = 3.88 + i * 0.55;

  // icon circle
  slide.addShape(pptx.ShapeType.ellipse, {
    x: 0.45, y: fy, w: 0.36, h: 0.36,
    fill: { color: C.teal },
    line: { color: C.teal },
  });
  slide.addText(f.icon, {
    x: 0.43, y: fy - 0.01, w: 0.4, h: 0.38,
    fontSize: 14,
    align: "center",
  });

  slide.addText(f.text, {
    x: 0.92, y: fy + 0.03, w: 10.5, h: 0.36,
    fontSize: 14,
    color: C.offWhite,
    fontFace: "Calibri",
  });
});

// ── Tech stack tag pills ──────────────────────────────────────────────────
const tags = ["FastAPI", "React + Vite", "SQLite", "Python 3.13", "OpenRouter AI", "Observability"];
const tagY = 5.62;
const tagH = 0.34;
let tagX = 0.45;

tags.forEach((tag) => {
  const tagW = tag.length * 0.115 + 0.36;
  slide.addShape(pptx.ShapeType.roundRect, {
    x: tagX, y: tagY, w: tagW, h: tagH,
    rectRadius: 0.09,
    fill: { color: "243050" },
    line: { color: C.orange, size: 0.8 },
  });
  slide.addText(tag, {
    x: tagX, y: tagY, w: tagW, h: tagH,
    fontSize: 10, bold: true,
    color: C.orange,
    fontFace: "Calibri",
    align: "center",
  });
  tagX += tagW + 0.14;
});

// ── Bottom footer ─────────────────────────────────────────────────────────
slide.addShape(pptx.ShapeType.rect, {
  x: 0, y: 7.16, w: "100%", h: 0.34,
  fill: { color: C.panel },
  line: { color: C.panel },
});

slide.addText("DRINKOO Control Room  •  github.com/cliuser677566/AI_TRAINING  •  2026", {
  x: 0.45, y: 7.18, w: 12, h: 0.28,
  fontSize: 9,
  color: C.muted,
  fontFace: "Calibri",
});

// ── Write file ────────────────────────────────────────────────────────────
const outPath = path.join(__dirname, "drinkoo_overview.pptx");
pptx.writeFile({ fileName: outPath })
  .then(() => console.log("CREATED:", outPath))
  .catch((err) => { console.error("FAILED:", err); process.exit(1); });
